//! Namespace results charge actual returned units before allocation.
use super::*;
#[test]
fn node_namespace_lookup_copy_and_result_refusal_leave_native_data_unchanged_and_recover(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);assert_eq!(page.console_eval(&mut doc,&mut forms,"var root=document.createElement('div');root.setAttributeNS('http://www.w3.org/2000/xmlns/','xmlns:p','uri\\ud800');").errors,0);let Value::Host(root)=page.runtime.execute("root",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("root")};page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let query=[Value::String("p".into())];assert!(matches!(b.native_namespace_lookup(root,&query,false).unwrap(),Value::StringUnits(_)));let before=(b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.attributes.len());let copies=b.state.copy_work;b.state.copy_work=0;assert!(b.native_namespace_lookup(root,&query,false).is_err());assert_eq!((b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.attributes.len()),before);assert!(matches!(b.native_namespace_lookup(root,&[Value::Null],true).unwrap(),Value::Null));b.state.copy_work=copies;let limit=b.state.limits.host.string_bytes;b.state.limits.host.string_bytes=1;assert!(b.native_namespace_lookup(root,&query,false).is_err());assert_eq!((b.state.retained,b.doc.nodes.len(),b.state.dom_commits,b.state.attributes.len()),before);b.state.limits.host.string_bytes=limit;let Value::StringUnits(units)=b.native_namespace_lookup(root,&query,false).unwrap()else{panic!("exact namespace units")};assert_eq!(units,vec![0x75,0x72,0x69,0xd800]);
}
